import { assert, assertEquals } from "jsr:@std/assert@1.0.13";
import { fcmPayload, safeEqual, sendFcm, signAssertion } from "./fcm.ts";

async function testAccount() {
  const pair = await crypto.subtle.generateKey(
    { name: "RSASSA-PKCS1-v1_5", modulusLength: 2048, publicExponent: new Uint8Array([1, 0, 1]), hash: "SHA-256" },
    true,
    ["sign", "verify"],
  );
  const der = new Uint8Array(await crypto.subtle.exportKey("pkcs8", pair.privateKey));
  let s = "";
  for (const b of der) s += String.fromCharCode(b);
  // A throwaway key generated by the test; signAssertion drops any PEM label.
  const pem = `-----BEGIN TEST KEY-----\n${btoa(s).match(/.{1,64}/g)!.join("\n")}\n-----END TEST KEY-----\n`;
  return { sa: { client_email: "push@test.invalid", private_key: pem }, publicKey: pair.publicKey };
}

function b64urlDecode(s: string): Uint8Array<ArrayBuffer> {
  const b = atob(s.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((s.length + 3) % 4));
  return Uint8Array.from(b, (c) => c.charCodeAt(0));
}

Deno.test("signAssertion: a verifiable RS256 JWT for the FCM scope", async () => {
  const { sa, publicKey } = await testAccount();
  const jwt = await signAssertion(sa, 1_800_000_000);
  const [h, c, sig] = jwt.split(".");
  const claims = JSON.parse(new TextDecoder().decode(b64urlDecode(c)));
  assertEquals(claims.iss, "push@test.invalid");
  assertEquals(claims.scope, "https://www.googleapis.com/auth/firebase.messaging");
  assertEquals(claims.exp - claims.iat, 3600);
  const ok = await crypto.subtle.verify(
    "RSASSA-PKCS1-v1_5",
    publicKey,
    b64urlDecode(sig),
    new TextEncoder().encode(`${h}.${c}`),
  );
  assert(ok, "signature verifies");
});

Deno.test("fcmPayload: title, body and only the kind as data", () => {
  const p = fcmPayload("tok", { title: "T", body: "B" }, "develop_reminder");
  assertEquals(p.message.token, "tok");
  assertEquals(p.message.notification, { title: "T", body: "B" });
  assertEquals(p.message.data, { kind: "develop_reminder" });
});

Deno.test("sendFcm: posts to the project's endpoint and returns status and body", async () => {
  let url = "";
  const fake = ((u: string) => {
    url = u;
    return Promise.resolve(new Response(JSON.stringify({ name: "x" }), { status: 200 }));
  }) as unknown as typeof fetch;
  const r = await sendFcm("b", "analog-archive-c184f", "tok", { title: "T", body: "B" }, "k", fake);
  assertEquals(url, "https://fcm.googleapis.com/v1/projects/analog-archive-c184f/messages:send");
  assertEquals(r.status, 200);
});

Deno.test("safeEqual", () => {
  assert(safeEqual("abc", "abc"));
  assert(!safeEqual("abc", "abd"));
  assert(!safeEqual("abc", "abcd"));
  assert(!safeEqual("", "x"));
});
